    "stem": "A 44-year-old man undergoes consultative review at Queen Elizabeth II Health Sciences Centre Halifax with clinical findings indicative of Meniere Disease with Recurrent Rotational Vertigo and Hearing Loss. Clinical examination and investigative review confirm dietary sodium restriction, betahistine, and thiazide diuretic maintenance. Vitals reveal blood pressure of 125/79 mm Hg, heart rate of 81/min, respiratory rate of 21/min, and temperature of 37.3C (98.7F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of meniere disease with recurrent rotational vertigo and hearing loss. What is the most definitive diagnostic investigation or guideline-directed intervention indicated for this patient?",
